('api_adjective_0', 'api', 'adjective', 0, 'Relating to an application programming interface; used to describe software components or systems that expose, consume, or interact via APIs.', '["API-based", "API-driven"]', '["non API-based", "manual integration"]', '["software attribute", "computing concept"]', '["REST API-based", "SOAP API-based"]', '["REST API", "API documentation", "API gateway", "API endpoint", "API specification", "API-first approach"]', '{"noun_forms": ["APIs"], "verb_forms": ["APIfy", "APIfying", "APIfied"], "adjective_forms": ["API-based", "API-driven"], "adverb_forms": ["API-wise"]}', '["An API-based architecture enables modular integration across services.", "The project adopted API-driven development to decouple front-end and back-end concerns."]', 'technology', 'BS', 16214, 12640, 'API', 'opengloss-v1.1'),
('api_noun_0', 'api', 'noun', 0, 'An API is a defined set of interfaces, protocols, and tools that enable software components to communicate and cooperate by specifying how to request services, pass data, and receive results.', '["programming interface", "software interface"]', '[]', '["interface", "software interface"]', '["REST API", "SOAP API", "GraphQL API"]', '["web API", "REST API", "API endpoint", "API documentation", "application programming interface", "public API"]', '{"noun_forms": ["application programming interface"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["Researchers integrated sensor data via the API.", "The API enables modular analysis workflows in experiments."]', 'technology', 'BS', 16214, 12640, 'API', 'opengloss-v1.1'),
('api_adjective_1', 'api', 'adjective', 1, 'Relating to active pharmaceutical ingredient; used as an attributive modifier in pharmacology to describe properties or considerations concerning the active drug substance in drug products.', '["drug component", "active ingredient"]', '["inactive ingredient", "excipients"]', '["chemical substance", "pharmaceutical component"]', '["active ingredient", "drug substance"]', '["REST API", "API documentation", "API gateway", "API endpoint", "API specification", "API-first approach"]', '{"noun_forms": ["APIs"], "verb_forms": ["APIfy", "APIfying", "APIfied"], "adjective_forms": ["API-based", "API-driven"], "adverb_forms": ["API-wise"]}', '["Stability of the API was evaluated under accelerated aging.", "The API content was quantified to ensure correct dosage."]', 'technology', 'BS', 16214, 12640, 'API', 'opengloss-v1.1'),
('api_noun_1', 'api', 'noun', 1, 'As a contractual boundary, an API specifies the available operations, input and output data formats, authentication, and error handling that govern interaction between software modules.', '["contract", "specification"]', '[]', '["interface", "software interface"]', '["public API", "private API", "internal API"]', '["web API", "REST API", "API endpoint", "API documentation", "application programming interface", "public API"]', '{"noun_forms": ["application programming interface"], "verb_forms": [], "adjective_forms": [], "adverb_forms": []}', '["The API contract specifies endpoints and data schemas.", "Documented error codes constitute the API''s external contract."]', 'technology', 'BS', 16214, 12640, 'API', 'opengloss-v1.1')
